import {HANDLING_FIELDS,HANDLING_PRESETS,handlingRules,fallSummary} from './handling-profile.js';
import {createMatch,step,pairAt} from './engine.js';
import {drawBoard,drawNext} from './render.js';

export function mountHandlingEditor(host,{prefs,onChange}){
 const $=q=>host.querySelector(q),scope=new AbortController();
 let game,raf,last=0,acc=0,actions=[],held=new Map();
 host.innerHTML=`<p class="muted">One handling profile for practice, duels and challenges. Changes apply straight away in duels and practice, and from the next run in other modes. Test them on the board below.</p><div class="handling-presets">${HANDLING_PRESETS.map(p=>`<button data-preset="${p.id}">${p.label}</button>`).join('')}</div><p class="fine-print">Presets are starting points. Lower numbers mean faster movement. Spawn adjustment is how long a new pair waits at the top, still movable, before it starts to fall. Early fast-fall window: press fast-fall this soon before the next pair appears and it drops straight away; holding through a landing never carries over.</p><div class="handling-editor"><div>${HANDLING_FIELDS.map(([key,label,min,max,step])=>`<label class="field-label">${label}<span class="range-row"><input data-speed-slider="${key}" type="range" aria-label="${label}" min="${min}" max="${max}" step="${step}"><input class="timing-number" data-speed-number="${key}" aria-label="${label} in milliseconds" type="number" min="${min}" max="${max}" step="1"><span>ms</span></span></label>`).join('')}<p id="fall-summary" class="fine-print"></p><button id="reset-handling" class="text-button">Restore build defaults</button></div><div class="handling-preview"><div class="handling-stage"><div class="handling-head"><strong>Test board</strong><div class="next-piece"><span>NEXT</span><canvas id="handling-next" aria-label="Next pair"></canvas></div></div><canvas tabindex="0" id="handling-board" aria-label="Handling test board. Focus to use your movement, rotation and fast fall keys."></canvas></div><p class="fine-print">Click the board, then use your controls. Tap to rotate; hold your fast-fall key to descend faster.</p><button id="clear-handling-board">Clear test board</button></div></div>`;
 const reset=()=>{game=createMatch({mode:'practice',seed:410,rules:handlingRules(prefs.rules)});actions=[];held.clear();acc=0;};
 function refresh(){for(const [key] of HANDLING_FIELDS){$(`[data-speed-slider="${key}"]`).value=prefs.rules[key];$(`[data-speed-number="${key}"]`).value=prefs.rules[key];}$('#fall-summary').textContent=fallSummary(prefs.rules);for(const el of host.querySelectorAll('[data-preset]'))el.classList.toggle('selected',HANDLING_PRESETS.find(p=>p.id===el.dataset.preset).rules.gravityMs===prefs.rules.gravityMs&&HANDLING_FIELDS.every(([key])=>HANDLING_PRESETS.find(p=>p.id===el.dataset.preset).rules[key]===prefs.rules[key]));}
 function update(rules){prefs.rules=handlingRules(rules);onChange();refresh();reset();}
 for(const el of host.querySelectorAll('[data-speed-slider]'))el.oninput=()=>update({...prefs.rules,[el.dataset.speedSlider]:Number(el.value)});
 for(const el of host.querySelectorAll('[data-speed-number]'))el.onchange=()=>{if(el.value!==''&&Number.isFinite(el.valueAsNumber))update({...prefs.rules,[el.dataset.speedNumber]:el.valueAsNumber});else refresh();};
 for(const el of host.querySelectorAll('[data-preset]'))el.onclick=()=>update(HANDLING_PRESETS.find(p=>p.id===el.dataset.preset).rules);
 $('#reset-handling').onclick=()=>update(HANDLING_PRESETS[1].rules);$('#clear-handling-board').onclick=reset;
 const canvas=$('#handling-board'),next=$('#handling-next');canvas.onclick=()=>canvas.focus();
 canvas.addEventListener('keydown',e=>{const action=Object.entries(prefs.keys).find(([,code])=>code===e.code)?.[0];if(!action||action==='pause')return;e.preventDefault();if(e.repeat)return;held.set(e.code,{action,next:game.elapsed+game.rules.repeatDelayMs});actions.push({side:0,action:action==='drop'?'fastOn':action});},{signal:scope.signal});
 window.addEventListener('keyup',e=>{const h=held.get(e.code);held.delete(e.code);if(h?.action==='drop')actions.push({side:0,action:'fastOff'});},{signal:scope.signal});
 canvas.addEventListener('blur',()=>{held.clear();actions=[{side:0,action:'fastOff'}];},{signal:scope.signal});
 function frame(time){if(!host.isConnected)return;const visible=!host.hidden&&!document.hidden;acc+=visible?Math.min(100,time-(last||time)):0;last=time;
  if(visible){while(acc>=1000/60){for(const h of held.values()){if(['left','right'].includes(h.action)&&game.elapsed>=h.next){actions.push({side:0,action:h.action});h.next=game.elapsed+game.rules.repeatMs;}if(game.version<10&&h.action==='drop'&&game.players[0].phase==='fall'&&!game.players[0].fast)actions.push({side:0,action:'fastOn'});}step(game,1000/60,actions);actions=[];acc-=1000/60;if(game.winner!==null)reset();}drawBoard(canvas,game.players[0],{time,gravityMs:game.rules.gravityMs,fastFallMs:game.rules.fastFallMs,renderAheadMs:acc,reduced:prefs.reduced});drawNext(next,pairAt(game.seed,game.players[0].nextIndex,game.rules.breakerRate));}
  raf=requestAnimationFrame(frame);
 }
 reset();refresh();raf=requestAnimationFrame(frame);return ()=>{scope.abort();cancelAnimationFrame(raf);};
}
